import subprocess,json
from pathlib import Path
REMOTE="from pathlib import Path\nfrom datetime import datetime,timezone\nimport json,hashlib\nstart=datetime.fromisoformat('2026-09-08T02:24:22+00:00');end=datetime.fromisoformat('2026-09-09T02:24:22+00:00')\ndef stamp(s):\n try:return datetime.fromisoformat(s.replace('Z','+00:00')).astimezone(timezone.utc)\n except (ValueError,TypeError,AttributeError):return None\ndef classify(s):return [k for k in ['504','502','timeout','budget','headers','body','ECONNRESET','UND_ERR_SOCKET'] if k in s]\nfail=[]\nfor p in Path('/var/lib/castreader-core-audio-monitor/us/results').glob('*.json'):\n v=json.loads(p.read_bytes());t=stamp(v.get('observedAt'))\n if not t or not start<=t<end or v.get('supplyOk') is True:continue\n row={'observedAtUTC':t.isoformat(),'filename':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'elapsedMs':v.get('elapsedMs'),'status':v.get('status'),'failureCode':v.get('failureCode'),'failedRequestContract':v.get('failedRequestContract'),'segmentCount':v.get('segmentCount'),'errorFieldTypes':{},'errorMatches':{}}\n for k,val in v.items():\n  if 'error' in k.lower() or 'failure' in k.lower():row['errorFieldTypes'][k]=type(val).__name__;row['errorMatches'][k]=classify(json.dumps(val))\n row['segments']=[{k:s.get(k) for k in ['index','attempts','requestContract','processedCharacters','remainingCharacters','audioBytes','upstreamNode']} for s in v.get('segments',[])]\n fail.append(row)\nprint(json.dumps({'window':{'startUTC':start.isoformat(),'endUTCExclusive':end.isoformat()},'monitorFailures':fail}))\n"
r=subprocess.run(['ssh','-T','-o','BatchMode=yes','-o','ConnectTimeout=10','root@140.82.14.49','python3 -B -'],input=REMOTE,text=True,capture_output=True,timeout=40)
if r.returncode:raise RuntimeError('read_failed')
v=json.loads(r.stdout)
Path(__file__).with_name('monitor-failures.json').write_text(json.dumps(v,indent=2))
print(json.dumps(v))
